    }

    public void popInsideScript() {
        insideScriptStack.pop();
        if (insideScriptStack.isEmpty()) {
            insideScript = false;
        } else {
            insideScript = this.insideScriptStack.peek();
        }
    }

    public void setAllowNextWhitespace() {
        allowNextWhitespace = true;
    }

